-- ============================================================
-- MirAcademy — "Dasturlash asoslari (Ma'ruza)": 20 ta mavzu taqdimoti
--
-- Har bir mavzu sahifasida "Taqdimot" tabida ochiladi.
-- Tarkib: hayotiy misol, asosiy g'oyalar, kod namunalari, ko'p
-- uchraydigan xato (xato / to'g'ri), savol, mini topshiriq, xulosa.
--
-- Sifat nazorati: kod slaydlaridagi "Natija" qo'lda yozilmagan —
-- generator har bir kodni Python'da ishga tushirib qo'ygan. "Kod nima
-- chiqaradi" savollarining to'g'ri javobi ham ishga tushirib tekshirilgan.
--
-- 73-migratsiyadan KEYIN ishga tushiring (slides ustuni).
-- Qayta ishga tushirish xavfsiz — taqdimot yangisi bilan almashadi.
-- ============================================================

DO $$
DECLARE
  v_course UUID;
  v_n INT;
  v_jami INT := 0;
BEGIN
  SELECT id INTO v_course FROM courses WHERE slug = 'dasturlash-asoslari-maruza';
  IF v_course IS NULL THEN
    RAISE EXCEPTION 'Kurs topilmadi: dasturlash-asoslari-maruza';
  END IF;

  UPDATE topics SET slides = $s$[{"t": "title", "title": "Python nima va nima uchun o'rganish kerak?", "subtitle": "Kompyuterga buyruq berishning eng sodda tili", "emoji": "🐍"}, {"t": "idea", "title": "Dastur — bu retsept", "text": "Osh pishirish retseptini eslang: guruchni yuving, sabzini to'g'rang, qozonni qizdiring. Har bir qadam aniq va tartib bilan.\n\nDastur ham xuddi shunday — kompyuter uchun yozilgan retsept. Faqat kompyuter juda \"so'zma-so'z\" o'qiydi: siz nima yozsangiz, aynan shuni bajaradi.", "emoji": "🍲"}, {"t": "points", "title": "Python qayerda ishlaydi?", "items": [{"e": "🤖", "text": "**Sun'iy intellekt** — ChatGPT kabi tizimlarni o'qitish asosan Python'da"}, {"e": "📊", "text": "**Ma'lumotlar tahlili** — bank, statistika, ilmiy tadqiqotlar"}, {"e": "🌐", "text": "**Veb-saytlar** — Instagram'ning server qismi Django'da yozilgan"}, {"e": "⚙️", "text": "**Avtomatlashtirish** — 100 ta faylni bir zumda qayta nomlash"}, {"e": "🎮", "text": "**O'yinlar va robotlar** — oddiy o'yinlardan Raspberry Pi robotlarigacha"}]}, {"t": "code", "title": "Birinchi dastur — bitta qator", "code": "print(\"Assalomu alaykum, Python!\")", "output": "Assalomu alaykum, Python!", "note": "`print()` — ekranga yozish buyrug'i. Qavs ichidagi matn qo'shtirnoqda bo'lishi shart."}, {"t": "code", "title": "Python kalkulyator ham", "code": "print(2026 - 2008)\nprint(15 * 12000)", "output": "18\n180000", "note": "Qo'shtirnoqsiz yozilgan son hisoblanadi: birinchi qator yoshni, ikkinchisi 15 ta non narxini topadi."}, {"t": "compare", "title": "Nima uchun aynan Python?", "left": {"label": "Boshqa tillarda", "code": "public class Salom {\n  public static void main(String[] a) {\n    System.out.println(\"Salom\");\n  }\n}"}, "right": {"label": "Python'da", "code": "print(\"Salom\")"}}, {"t": "quiz", "question": "Kod nima chiqaradi?", "options": ["53", "5 + 3", "Xato", "8"], "answer": 3, "explain": "Qo'shtirnoqsiz `5 + 3` — hisoblanadigan ifoda, natijasi 8.", "code": "print(5 + 3)"}, {"t": "quiz", "question": "Kod nima chiqaradi?", "options": ["Xato", "5 + 3", "8", "53"], "answer": 1, "explain": "Qo'shtirnoq ichidagi hamma narsa oddiy matn — Python uni hisoblamaydi, shundayligicha chiqaradi.", "code": "print(\"5 + 3\")"}, {"t": "task", "title": "Ismingizni chiqaring", "text": "Ekranga ikki qator chiqaring: birinchisida ismingiz, ikkinchisida tug'ilgan yilingizdan beri necha yil o'tganini Python hisoblasin.", "starter": "print(\"Ismim: ...\")\nprint(2026 - ...)", "hint": "Ism — qo'shtirnoqda, hisob — qo'shtirnoqsiz."}, {"t": "summary", "title": "Bugun nimani bildik", "items": ["Dastur — kompyuter uchun aniq retsept", "Python sodda yoziladi va AI, veb, tahlilda ishlatiladi", "`print()` ekranga chiqaradi", "Qo'shtirnoqdagi matn — matn, qo'shtirnoqsiz ifoda — hisoblanadi"]}]$s$::jsonb
   WHERE course_id = v_course AND slug = 'python-intro';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN RAISE WARNING 'Mavzu topilmadi: python-intro'; END IF;
  v_jami := v_jami + v_n;

  UPDATE topics SET slides = $s$[{"t": "title", "title": "Python o'rnatish va muhitni sozlash", "subtitle": "Ish stolini tayyorlaymiz", "emoji": "🧰"}, {"t": "idea", "title": "Usta asbobsiz ishlamaydi", "text": "Duradgor ish boshlashdan oldin arra, randa va o'lchov chizg'ichini tayyorlaydi. Dasturchining asboblari: **Python tarjimoni** (kodni bajaradi) va **muharrir** (kod yoziladigan joy).", "emoji": "🪚"}, {"t": "points", "title": "Uchta yo'l — o'zingizga qulayini tanlang", "items": [{"e": "🌐", "text": "**Brauzerda** — MirAcademy Playground: hech narsa o'rnatmasdan darhol yozing"}, {"e": "💻", "text": "**Kompyuterda** — python.org dan Python + VS Code muharriri"}, {"e": "📱", "text": "**Telefonda** — Pydroid 3 ilovasi (Android)"}]}, {"t": "points", "title": "Windows'da o'rnatish qadamlari", "items": [{"e": "1️⃣", "text": "python.org → Downloads → eng so'nggi versiyani yuklab oling"}, {"e": "2️⃣", "text": "O'rnatishning birinchi oynasida **Add python.exe to PATH** belgisini qo'ying"}, {"e": "3️⃣", "text": "Install Now tugmasini bosing"}, {"e": "4️⃣", "text": "Terminalni oching va `python --version` yozing"}]}, {"t": "compare", "title": "Eng ko'p uchraydigan xato", "left": {"label": "PATH belgilanmagan", "code": "C:\\> python --version\n'python' is not recognized as an internal\nor external command"}, "right": {"label": "PATH belgilangan", "code": "C:\\> python --version\nPython 3.13.0"}}, {"t": "code", "title": "Ishlayotganini tekshirish", "code": "import sys\nprint(\"Python ishlayapti!\")\nprint(sys.version_info.major)", "output": "Python ishlayapti!\n3", "note": "Birinchi qator Python haqida ma'lumot beruvchi modulni ulaydi. Natijada versiyaning bosh raqami chiqadi."}, {"t": "table", "title": "Fayl va muhit haqida", "head": ["Narsa", "Ma'nosi"], "rows": [["`dastur.py`", "Python fayli — kengaytmasi doim `.py`"], ["Interaktiv rejim (`>>>`)", "Bir qatorlab sinash, natija darhol chiqadi"], ["Terminal / konsol", "Dastur natijasi va xatolari chiqadigan oyna"], ["Muharrir (VS Code)", "Kodni yozish, rang berish, xatoni ko'rsatish"]]}, {"t": "quiz", "question": "Windows'da o'rnatishda qaysi belgini qo'yish eng muhim?", "options": ["Hech biri", "Add python.exe to PATH", "Disable path length limit", "Install for all users"], "answer": 1, "explain": "PATH bo'lmasa, terminal `python` buyrug'ini tanimaydi va har safar to'liq yo'lni yozishga to'g'ri keladi."}, {"t": "task", "title": "Muhitni sinab ko'ring", "text": "Playground'da quyidagi kodni ishga tushiring, keyin `print` ichidagi matnni o'zingizniki bilan almashtiring.", "starter": "print(\"Mening birinchi muhitim tayyor!\")\nprint(7 * 24, \"soat — bir haftada\")", "hint": "Ikkinchi qatorda vergul bilan bir nechta qiymat chiqarilgan — ular orasiga bo'shliq qo'yiladi."}, {"t": "summary", "title": "Esda qoldiring", "items": ["Python tarjimoni + muharrir = ish muhiti", "Windows'da **Add to PATH** belgisini unutmang", "`python --version` — o'rnatilganini tekshirish", "Boshlash uchun o'rnatish shart emas — Playground yetarli"]}]$s$::jsonb
   WHERE course_id = v_course AND slug = 'python-setup';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN RAISE WARNING 'Mavzu topilmadi: python-setup'; END IF;
  v_jami := v_jami + v_n;

  UPDATE topics SET slides = $s$[{"t": "title", "title": "Python sintaksisi", "subtitle": "Kompyuter bilan gaplashish grammatikasi", "emoji": "✍️"}, {"t": "idea", "title": "Tinish belgisi ma'noni o'zgartiradi", "text": "\"Kechirish mumkin emas, qatl qilinsin\" va \"Kechirish mumkin, emas qatl qilinsin\" — bitta vergul taqdirni hal qildi.\n\nPython'da ham kichik belgi — ikki nuqta, bo'shliq, qavs — dastur ma'nosini o'zgartiradi.", "emoji": "📜"}, {"t": "points", "title": "Uchta oltin qoida", "items": [{"e": "↳", "text": "**Chekinish** blokni belgilaydi — odatda 4 ta bo'shliq"}, {"e": "：", "text": "`if`, `for`, `def` qatori **ikki nuqta** bilan tugaydi"}, {"e": "Aa", "text": "Katta-kichik harf farqlanadi: `Ism` va `ism` — boshqa-boshqa nom"}]}, {"t": "code", "title": "Blok qanday ko'rinadi", "code": "harorat = 32\nif harorat > 30:\n    print(\"Issiq!\")\n    print(\"Suv iching\")\nprint(\"Kun yaxshi o'tsin\")", "output": "Issiq!\nSuv iching\nKun yaxshi o'tsin", "note": "Chekingan ikki qator `if` ga tegishli. Oxirgi qator chekinmagan — u shartdan qat'i nazar bajariladi."}, {"t": "compare", "title": "Chekinish xatosi", "left": {"label": "Xato", "code": "if 5 > 3:\nprint(\"salom\")"}, "right": {"label": "To'g'ri", "code": "if 5 > 3:\n    print(\"salom\")"}}, {"t": "code", "title": "Izoh — odamlar uchun yozuv", "code": "# Bu qatorni Python o'qimaydi\nnarx = 12000  # bitta non narxi\nprint(narx * 3)", "output": "36000", "note": "`#` dan keyingi hamma narsa izoh. Kodni o'qiyotgan odamga tushuntirish uchun yoziladi."}, {"t": "code", "title": "input() — foydalanuvchidan so'rash", "code": "ism = input()\nprint(\"Xush kelibsiz,\", ism)", "input": "Dilnoza", "output": "Xush kelibsiz, Dilnoza", "note": "`input()` foydalanuvchi yozgan matnni qaytaradi. Bu yerda u `ism` o'zgaruvchisiga saqlandi."}, {"t": "quiz", "question": "Qaysi qatorda sintaksis xatosi bor?", "options": ["`# izoh`", "`print(x)`", "`if x > 0`", "`x = 5`"], "answer": 2, "explain": "`if` qatori ikki nuqta bilan tugashi shart: `if x > 0:`"}, {"t": "quiz", "question": "Kod nima chiqaradi?", "options": ["A\nB", "B", "Hech narsa", "A"], "answer": 1, "explain": "Shart yolg'on — chekingan `print(\"A\")` bajarilmaydi. `print(\"B\")` chekinmagan, u har doim ishlaydi.", "code": "x = 2\nif x > 5:\n    print(\"A\")\nprint(\"B\")"}, {"t": "task", "title": "Ob-havo maslahatchisi", "text": "Haroratni so'rang. Agar 30 dan yuqori bo'lsa \"Shlyapa kiying\", aks holda \"Yaxshi kun\" deb chiqaring.", "starter": "harorat = int(input())\nif harorat > 30:\n    print(...)\nelse:\n    print(...)", "hint": "`else:` ham ikki nuqta bilan tugaydi va undan keyingi qator chekinadi."}, {"t": "summary", "title": "Sintaksis — qisqacha", "items": ["Blok chekinish bilan belgilanadi, 4 ta bo'shliq", "Boshqaruv qatori ikki nuqta bilan tugaydi", "Katta-kichik harf farq qiladi", "`#` — izoh, `input()` — so'rash, `print()` — chiqarish"]}]$s$::jsonb
   WHERE course_id = v_course AND slug = 'python-sintaksis';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN RAISE WARNING 'Mavzu topilmadi: python-sintaksis'; END IF;
  v_jami := v_jami + v_n;

  UPDATE topics SET slides = $s$[{"t": "title", "title": "Python'dagi xatoliklar", "subtitle": "Xato — dushman emas, maslahatchi", "emoji": "🐞"}, {"t": "idea", "title": "Xato xabari — navigator ovozi", "text": "Taksida navigator \"300 metrdan keyin o'ngga buriling\" deydi. Python xatosi ham xuddi shunday: **qaysi qatorda** va **nima** noto'g'ri ekanini aytadi. Uni o'qishni o'rgansangiz, xatoni topish 10 soniya oladi.", "emoji": "🧭"}, {"t": "table", "title": "Xato turlari", "head": ["Xato", "Qachon chiqadi", "Misol"], "rows": [["`SyntaxError`", "Grammatika buzilgan", "`print(\"salom\"`"], ["`NameError`", "Nom topilmadi", "`prnt(5)`"], ["`TypeError`", "Tur mos emas", "`\"5\" + 5`"], ["`ValueError`", "Qiymat noto'g'ri", "`int(\"abc\")`"], ["`ZeroDivisionError`", "Nolga bo'lish", "`10 / 0`"], ["`IndexError`", "Indeks yo'q", "`[1, 2][5]`"]]}, {"t": "code", "title": "NameError — yozuvdagi xato", "code": "ism = \"Ali\"\nprint(Ism)", "output": "NameError: name 'Ism' is not defined", "note": "Python `Ism` ni tanimadi, chunki o'zgaruvchi kichik harf bilan `ism` deb yaratilgan."}, {"t": "code", "title": "TypeError — matn va son", "code": "yosh = \"19\"\nprint(yosh + 1)", "output": "TypeError: can only concatenate str (not \"int\") to str", "note": "`input()` doim matn qaytaradi. Son kerak bo'lsa — `int()` bilan aylantiring."}, {"t": "points", "title": "Xato xabarini o'qish tartibi", "items": [{"e": "1️⃣", "text": "**Oxirgi qatorni** o'qing — xato turi va qisqa izoh"}, {"e": "2️⃣", "text": "`line N` — xato qaysi qatorda"}, {"e": "3️⃣", "text": "O'sha qatorni va undan oldingisini tekshiring"}, {"e": "4️⃣", "text": "Tuzating, qayta ishga tushiring"}]}, {"t": "compare", "title": "Mantiqiy xato — eng ayyori", "left": {"label": "Xato chiqmaydi, lekin natija noto'g'ri", "code": "son = input()\nprint(son * 2)   # 5 kiritilsa: 55"}, "right": {"label": "To'g'ri", "code": "son = int(input())\nprint(son * 2)   # 5 kiritilsa: 10"}}, {"t": "quiz", "question": "`int(\"12a\")` qaysi xatoni beradi?", "options": ["NameError", "SyntaxError", "TypeError", "ValueError"], "answer": 3, "explain": "Turi to'g'ri (matn), lekin qiymat songa aylanmaydi — bu ValueError.", "code": "try:\n    int(\"12a\")\nexcept Exception as e:\n    print(type(e).__name__)"}, {"t": "task", "title": "Xatoni toping va tuzating", "text": "Kod ikki son yig'indisini chiqarishi kerak, lekin noto'g'ri ishlaydi. Tuzating.", "starter": "a = input()\nb = input()\nprint(\"Yig'indi:\", a + b)", "hint": "`input()` matn qaytaradi: \"3\" + \"4\" = \"34\". Ikkalasini `int()` ga o'rang."}, {"t": "summary", "title": "Xatolar bilan do'stlashing", "items": ["Xato xabarining oxirgi qatoridan boshlang", "`line N` — qidirish joyi", "Eng ko'p xato: matnni son deb o'ylash", "Xato chiqmagan, lekin natija noto'g'ri bo'lsa — mantiqiy xato"]}]$s$::jsonb
   WHERE course_id = v_course AND slug = 'python-xatoliklar';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN RAISE WARNING 'Mavzu topilmadi: python-xatoliklar'; END IF;
  v_jami := v_jami + v_n;

  UPDATE topics SET slides = $s$[{"t": "title", "title": "Arifmetik amallar", "subtitle": "Python — juda tez kalkulyator", "emoji": "🧮"}, {"t": "idea", "title": "Bozordagi hisob", "text": "3 kg olma 14 000 so'mdan, 2 kg uzum 22 000 so'mdan. 100 000 so'm bersangiz, qancha qaytim olasiz? Bunday hisobni Python ko'z ochib yumguncha bajaradi.", "emoji": "🍎"}, {"t": "table", "title": "Yetti amal", "head": ["Amal", "Belgi", "Misol", "Natija"], "rows": [["Qo'shish", "`+`", "`7 + 2`", "9"], ["Ayirish", "`-`", "`7 - 2`", "5"], ["Ko'paytirish", "`*`", "`7 * 2`", "14"], ["Bo'lish", "`/`", "`7 / 2`", "3.5"], ["Butun bo'lish", "`//`", "`7 // 2`", "3"], ["Qoldiq", "`%`", "`7 % 2`", "1"], ["Daraja", "`**`", "`7 ** 2`", "49"]]}, {"t": "code", "title": "Bozor hisobi", "code": "olma = 3 * 14000\nuzum = 2 * 22000\njami = olma + uzum\nprint(\"Jami:\", jami)\nprint(\"Qaytim:\", 100000 - jami)", "output": "Jami: 86000\nQaytim: 14000"}, {"t": "code", "title": "// va % — hayotdagi o'rni", "code": "daqiqa = 135\nprint(daqiqa // 60, \"soat\")\nprint(daqiqa % 60, \"daqiqa\")", "output": "2 soat\n15 daqiqa", "note": "135 daqiqa = 2 soat 15 daqiqa. `//` butun qismini, `%` qolganini beradi."}, {"t": "compare", "title": "Amallar tartibi", "left": {"label": "Kutilmagan natija", "code": "print(2 + 3 * 4)   # 14, 20 emas"}, "right": {"label": "Qavs bilan", "code": "print((2 + 3) * 4)   # 20"}}, {"t": "code", "title": "Juftmi yoki toq?", "code": "for son in [10, 7, 0]:\n    print(son, \"->\", son % 2)", "output": "10 -> 0\n7 -> 1\n0 -> 0", "note": "Juft sonning 2 ga bo'lgandagi qoldig'i doim 0. Bu usul juda ko'p masalada ishlatiladi."}, {"t": "quiz", "question": "Kod nima chiqaradi?", "options": ["3", "1", "2.5", "2"], "answer": 3, "explain": "`//` — butun bo'lish: kasr qismi tashlab yuboriladi.", "code": "print(17 // 7)"}, {"t": "quiz", "question": "Kod nima chiqaradi?", "options": ["512", "18", "64", "81"], "answer": 0, "explain": "Daraja o'ngdan chapga hisoblanadi: `3 ** 2` = 9, keyin `2 ** 9` = 512.", "code": "print(2 ** 3 ** 2)"}, {"t": "task", "title": "Taksi hisobi", "text": "Taksi tarifi: o'tirish 5 000 so'm, har kilometr 2 500 so'm. Masofani (km) so'rab, to'lov summasini chiqaring.", "starter": "km = int(input())\n# narxni hisoblang\nprint(...)", "hint": "5000 + km * 2500 — ko'paytirish birinchi bajariladi, qavs shart emas."}, {"t": "summary", "title": "Arifmetika — qisqacha", "items": ["`/` doim kasr son beradi, `//` — butun qismini", "`%` — qoldiq: juftlik, soat-daqiqa masalalarida", "`**` — daraja, u o'ngdan chapga hisoblanadi", "Tartib shubhali bo'lsa — qavs qo'ying"]}]$s$::jsonb
   WHERE course_id = v_course AND slug = 'arifmetik-amallar';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN RAISE WARNING 'Mavzu topilmadi: arifmetik-amallar'; END IF;
  v_jami := v_jami + v_n;

  UPDATE topics SET slides = $s$[{"t": "title", "title": "O'zgaruvchilar va ma'lumot turlari", "subtitle": "Qiymatlarni yorliqli qutilarga joylaymiz", "emoji": "📦"}, {"t": "idea", "title": "O'zgaruvchi — yorliqli quti", "text": "Ko'chishda qutilarga \"Idishlar\", \"Kitoblar\" deb yozasiz. Keyin \"Kitoblar\" qutisini nomidan topasiz.\n\nO'zgaruvchi ham shunday: `narx = 12000` — \"narx\" degan quti, ichida 12000.", "emoji": "🏷️"}, {"t": "table", "title": "Asosiy turlar", "head": ["Tur", "Nimani saqlaydi", "Misol"], "rows": [["`int`", "Butun son", "`yosh = 19`"], ["`float`", "Kasr son", "`bo_y = 1.75`"], ["`str`", "Matn", "`ism = \"Ali\"`"], ["`bool`", "Ha / yo'q", "`talaba = True`"]]}, {"t": "code", "title": "type() — qutining ichida nima bor?", "code": "print(type(19))\nprint(type(1.75))\nprint(type(\"19\"))\nprint(type(True))", "output": "<class 'int'>\n<class 'float'>\n<class 'str'>\n<class 'bool'>", "note": "`19` va `\"19\"` — butunlay boshqa narsalar: biri son, biri matn."}, {"t": "code", "title": "Qiymat o'zgarishi mumkin", "code": "balans = 50000\nbalans = balans - 12000\nbalans += 3000\nprint(balans)", "output": "41000", "note": "`balans += 3000` — `balans = balans + 3000` ning qisqa yozuvi."}, {"t": "code", "title": "Turlarni aylantirish", "code": "yosh = int(\"19\")\nnarx = float(\"12.5\")\nmatn = str(2026)\nprint(yosh + 1, narx * 2, matn + \"-yil\")", "output": "20 25.0 2026-yil"}, {"t": "compare", "title": "Nomlash qoidalari", "left": {"label": "Mumkin emas", "code": "2ism = \"Ali\"     # raqam bilan boshlanadi\nmening ism = 5   # bo'shliq\nfor = 3          # kalit so'z"}, "right": {"label": "To'g'ri", "code": "ism2 = \"Ali\"\nmening_ismim = 5\nsoni = 3"}}, {"t": "quiz", "question": "Kod nima chiqaradi?", "options": ["<class 'int'>", "<class 'str'>", "Xato", "<class 'float'>"], "answer": 1, "explain": "Qo'shtirnoq ichidagi har qanday narsa — matn, hatto u raqamga o'xshasa ham.", "code": "print(type(\"3.14\"))"}, {"t": "quiz", "question": "Kod nima chiqaradi?", "options": ["9", "99", "18", "Xato"], "answer": 0, "explain": "`int(9.99)` yaxlitlamaydi, kasr qismini kesib tashlaydi.", "code": "print(int(9.99))"}, {"t": "task", "title": "Stipendiya kalkulyatori", "text": "Oylik stipendiyani (butun son) so'rang. Bir yillik summani va oyiga 15% tejalsa yil oxirida qancha yig'ilishini chiqaring.", "starter": "oylik = int(input())\nyillik = ...\ntejash = ...\nprint(yillik)\nprint(tejash)", "hint": "15% — bu `0.15` ga ko'paytirish. Natija `float` bo'lishi mumkin."}, {"t": "summary", "title": "Esda qoldiring", "items": ["O'zgaruvchi — nomli quti, `=` qiymat beradi", "To'rt asosiy tur: `int`, `float`, `str`, `bool`", "`type()` turini ko'rsatadi, `int()`/`float()`/`str()` aylantiradi", "Nom raqam bilan boshlanmaydi, bo'shliq bo'lmaydi"]}]$s$::jsonb
   WHERE course_id = v_course AND slug = 'ozgaruvchilar-va-turlar';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN RAISE WARNING 'Mavzu topilmadi: ozgaruvchilar-va-turlar'; END IF;
  v_jami := v_jami + v_n;

  UPDATE topics SET slides = $s$[{"t": "title", "title": "Matnlar va sonlar bilan ishlash", "subtitle": "Satrlarni kesamiz, yopishtiramiz, bezaymiz", "emoji": "🔤"}, {"t": "idea", "title": "Satr — munchoq ipi", "text": "Satrni munchoqlar tizilgan ip deb tasavvur qiling: har bir harf — bitta munchoq, har birining tartib raqami bor. Birinchisi **0**-raqam!", "emoji": "📿"}, {"t": "code", "title": "Indeks va kesim", "code": "s = \"PYTHON\"\nprint(s[0], s[-1])\nprint(s[0:3])\nprint(s[::-1])", "output": "P N\nPYT\nNOHTYP", "note": "`s[0:3]` — 0, 1, 2-harflar (3 kirmaydi). `[::-1]` — teskari."}, {"t": "table", "title": "Kerakli metodlar", "head": ["Metod", "Nima qiladi", "Natija"], "rows": [["`\"ali\".upper()`", "Katta harf", "`ALI`"], ["`\"  salom \".strip()`", "Chetdagi bo'shliqni olib tashlaydi", "`salom`"], ["`\"a-b-c\".split(\"-\")`", "Bo'laklarga ajratadi", "`['a', 'b', 'c']`"], ["`\"olma\".replace(\"o\", \"O\")`", "Almashtiradi", "`Olma`"], ["`len(\"salom\")`", "Uzunlik", "`5`"]]}, {"t": "code", "title": "f-satr — matnga qiymat qo'shish", "code": "ism = \"Sardor\"\nball = 87.456\nprint(f\"{ism} {ball:.1f} ball oldi\")", "output": "Sardor 87.5 ball oldi", "note": "`f` harfi va jingalak qavslar. `:.1f` — verguldan keyin 1 xona."}, {"t": "compare", "title": "Matn va son qo'shilmaydi", "left": {"label": "Xato", "code": "yosh = 19\nprint(\"Yoshim: \" + yosh)"}, "right": {"label": "To'g'ri", "code": "yosh = 19\nprint(\"Yoshim: \" + str(yosh))\nprint(f\"Yoshim: {yosh}\")"}}, {"t": "code", "title": "Telefon raqamini bezash", "code": "tel = \"998901234567\"\nprint(f\"+{tel[:3]} ({tel[3:5]}) {tel[5:8]}-{tel[8:10]}-{tel[10:]}\")", "output": "+998 (90) 123-45-67"}, {"t": "quiz", "question": "Kod nima chiqaradi?", "options": ["thon", "pyt", "ytho", "tho"], "answer": 3, "explain": "2, 3, 4-indekslar: t, h, o. 5-indeks kirmaydi.", "code": "print(\"python\"[2:5])"}, {"t": "quiz", "question": "Kod nima chiqaradi?", "options": ["4", "2", "1", "3"], "answer": 3, "explain": "`split()` bo'shliqlar bo'yicha bo'ladi: ['bir', 'ikki', 'uch'].", "code": "print(len(\"bir ikki uch\".split()))"}, {"t": "task", "title": "Login yasash", "text": "Ism va familiyani so'rang. Login quyidagicha bo'lsin: familiya kichik harflarda + ismning birinchi harfi. Masalan: Ali Valiyev → valiyeva", "starter": "ism = input()\nfamiliya = input()\nlogin = ...\nprint(login)", "hint": "`familiya.lower() + ism[0].lower()`"}, {"t": "summary", "title": "Satrlar — qisqacha", "items": ["Indeks 0 dan boshlanadi, `-1` — oxirgisi", "Kesim `[a:b]` — b kirmaydi", "Satr o'zgarmaydi: metodlar yangi satr qaytaradi", "Son va matnni f-satr bilan birlashtiring"]}]$s$::jsonb
