  UPDATE topics SET slides = $s$[{"t": "title", "title": "Ro'yxatlar va for sikli", "subtitle": "Ko'p qiymatni bitta joyda saqlash va aylanib chiqish", "emoji": "📋"}, {"t": "idea", "title": "Ro'yxat — xarid qog'ozi", "text": "Bozorga borishdan oldin yozasiz: non, sut, tuxum, guruch. Keyin har birini **navbat bilan** olasiz.\n\nPython'da: `xarid = [\"non\", \"sut\", \"tuxum\"]`, navbat bilan olish esa — `for` sikli.", "emoji": "🛒"}, {"t": "code", "title": "Ro'yxat bilan ishlash", "code": "xarid = [\"non\", \"sut\", \"tuxum\"]\nxarid.append(\"guruch\")\nprint(xarid[0], len(xarid))\nxarid.remove(\"sut\")\nprint(xarid)", "output": "non 4\n['non', 'tuxum', 'guruch']"}, {"t": "code", "title": "for — har biriga navbat bilan", "code": "baholar = [5, 4, 5, 3]\nfor b in baholar:\n    print(\"Baho:\", b)\nprint(\"O'rtacha:\", sum(baholar) / len(baholar))", "output": "Baho: 5\nBaho: 4\nBaho: 5\nBaho: 3\nO'rtacha: 4.25"}, {"t": "code", "title": "range() — sonlar ketma-ketligi", "code": "for i in range(1, 6):\n    print(i, \"x 7 =\", i * 7)", "output": "1 x 7 = 7\n2 x 7 = 14\n3 x 7 = 21\n4 x 7 = 28\n5 x 7 = 35", "note": "`range(1, 6)` — 1, 2, 3, 4, 5. Oxirgi son kirmaydi."}, {"t": "table", "title": "range() variantlari", "head": ["Yozuv", "Sonlar"], "rows": [["`range(5)`", "0 1 2 3 4"], ["`range(2, 6)`", "2 3 4 5"], ["`range(0, 10, 3)`", "0 3 6 9"], ["`range(5, 0, -1)`", "5 4 3 2 1"]]}, {"t": "compare", "title": "Indeks chegarasi", "left": {"label": "Xato: 3 ta element, oxirgi indeks 2", "code": "a = [10, 20, 30]\nprint(a[3])"}, "right": {"label": "To'g'ri", "code": "a = [10, 20, 30]\nprint(a[2], a[-1])"}}, {"t": "quiz", "question": "Kod nima chiqaradi?", "options": ["0", "15", "4", "10"], "answer": 3, "explain": "range(5) — 0, 1, 2, 3, 4. Ularning yig'indisi 10.", "code": "s = 0\nfor i in range(5):\n    s += i\nprint(s)"}, {"t": "task", "title": "Eng issiq kun", "text": "Haftaning 7 kunlik haroratlari ro'yxatda berilgan. Eng yuqori va eng past haroratni hamda o'rtachasini chiqaring.", "starter": "harorat = [28, 31, 35, 33, 29, 26, 30]\n# max, min va o'rtacha", "hint": "`max()`, `min()`, `sum() / len()`"}, {"t": "summary", "title": "Ro'yxat va for", "items": ["Ro'yxat `[ ]` ichida, elementlari vergul bilan", "`append` qo'shadi, `remove` o'chiradi, `len` sanaydi", "`for x in royxat:` — har bir element bilan ishlash", "`range(a, b)` da b kirmaydi"]}]$s$::jsonb
