  UPDATE topics SET slides = $s$[{"t": "title", "title": "Shartlar va tarmoqlanish", "subtitle": "Dastur qaror qabul qilishni o'rganadi", "emoji": "🔀"}, {"t": "idea", "title": "Svetofor qoidasi", "text": "Yashil — yuring, sariq — tayyorlaning, qizil — to'xtang. Haydovchi har safar rangga qarab **qaror** qiladi.\n\nDastur ham `if`, `elif`, `else` bilan shunday qaror qiladi.", "emoji": "🚦"}, {"t": "code", "title": "Svetofor dasturda", "code": "rang = \"sariq\"\nif rang == \"yashil\":\n    print(\"Yuring\")\nelif rang == \"sariq\":\n    print(\"Tayyorlaning\")\nelse:\n    print(\"To'xtang\")", "output": "Tayyorlaning"}, {"t": "table", "title": "Solishtirish amallari", "head": ["Belgi", "Ma'nosi", "Misol"], "rows": [["`==`", "teng", "`x == 5`"], ["`!=`", "teng emas", "`x != 0`"], ["`>` `<`", "katta / kichik", "`ball > 85`"], ["`>=` `<=`", "katta-teng / kichik-teng", "`yosh >= 18`"]]}, {"t": "code", "title": "Baho shkalasi", "code": "ball = 78\nif ball >= 86:\n    print(\"A'lo\")\nelif ball >= 71:\n    print(\"Yaxshi\")\nelif ball >= 56:\n    print(\"Qoniqarli\")\nelse:\n    print(\"Qayta topshirish\")", "output": "Yaxshi", "note": "Shartlar yuqoridan pastga tekshiriladi va birinchi rost kelgani bajariladi."}, {"t": "code", "title": "and / or — bir nechta shart", "code": "yosh = 20\nguvohnoma = True\nif yosh >= 18 and guvohnoma:\n    print(\"Mashina haydash mumkin\")", "output": "Mashina haydash mumkin"}, {"t": "compare", "title": "= va == ni chalkashtirish", "left": {"label": "Xato", "code": "if ball = 100:\n    print(\"Maksimal\")"}, "right": {"label": "To'g'ri", "code": "ball = 100\nif ball == 100:\n    print(\"Maksimal\")"}}, {"t": "quiz", "question": "Kod nima chiqaradi?", "options": ["C", "B", "A", "A\nB"], "answer": 1, "explain": "15 > 10 rost, lekin birinchi shart `x > 20` yolg'on. `elif` ishlaydi va qolganlari tekshirilmaydi.", "code": "x = 15\nif x > 20:\n    print(\"A\")\nelif x > 10:\n    print(\"B\")\nelse:\n    print(\"C\")"}, {"t": "task", "title": "Kino chiptasi", "text": "Yoshni so'rang. 7 yoshgacha — bepul, 7–17 — 20 000 so'm, 18–59 — 40 000 so'm, 60 dan yuqori — 15 000 so'm. Narxni chiqaring.", "starter": "yosh = int(input())\nif yosh < 7:\n    print(0)\n# davom ettiring", "hint": "Shartlarni kichik yoshdan kattaga qarab `elif` bilan yozing."}, {"t": "summary", "title": "Qaror qabul qilish", "items": ["`if` → `elif` → `else`, har biri ikki nuqta bilan", "Birinchi rost shart bajariladi, qolganlari o'tkazib yuboriladi", "`==` solishtiradi, `=` qiymat beradi", "`and` — ikkalasi ham, `or` — kamida bittasi"]}]$s$::jsonb
