  UPDATE topics SET slides = $s$[{"t": "title", "title": "Lug'at va to'plam", "subtitle": "Nom bo'yicha topish va takrorlarni yo'qotish", "emoji": "🗂️"}, {"t": "idea", "title": "Lug'at — telefon kontaktlari", "text": "Telefoningizda \"Onam\" deb qidirasiz va raqam chiqadi. Raqamni yodlash shart emas — **nom** kalit, raqam — qiymat.\n\nPython lug'ati xuddi shunday: `{\"Onam\": \"901234567\"}`", "emoji": "📱"}, {"t": "code", "title": "Lug'at bilan ishlash", "code": "kontakt = {\"Onam\": \"901112233\", \"Akam\": \"935556677\"}\nprint(kontakt[\"Onam\"])\nkontakt[\"Do'stim\"] = \"977778899\"\nprint(len(kontakt))\nprint(kontakt.get(\"Opam\", \"topilmadi\"))", "output": "901112233\n3\ntopilmadi"}, {"t": "code", "title": "Lug'atni aylanib chiqish", "code": "narxlar = {\"non\": 4000, \"sut\": 12000, \"tuxum\": 1500}\nfor nom, narx in narxlar.items():\n    print(f\"{nom:6} {narx:>6} so'm\")", "output": "non      4000 so'm\nsut     12000 so'm\ntuxum    1500 so'm"}, {"t": "idea", "title": "To'plam — mehmonlar ro'yxati", "text": "To'yga taklifnoma tarqatyapsiz. Bir odamning ismi ikki marta yozilib qolsa ham, unga bitta taklifnoma yetadi.\n\n**To'plam** (`set`) takrorlarni o'zi olib tashlaydi.", "emoji": "💌"}, {"t": "code", "title": "To'plam amallari", "code": "python = {\"Ali\", \"Vali\", \"Dilnoza\"}\nweb = {\"Vali\", \"Sardor\"}\nprint(sorted(python & web))\nprint(sorted(python | web))\nprint(len({1, 1, 2, 2, 3}))", "output": "['Vali']\n['Ali', 'Dilnoza', 'Sardor', 'Vali']\n3", "note": "`&` — ikkalasida ham bor, `|` — hammasi birga."}, {"t": "compare", "title": "Yo'q kalitga murojaat", "left": {"label": "Xato beradi", "code": "d = {\"a\": 1}\nprint(d[\"b\"])"}, "right": {"label": "Xavfsiz", "code": "d = {\"a\": 1}\nprint(d.get(\"b\", 0))"}}, {"t": "quiz", "question": "Kod nima chiqaradi?", "options": ["1", "6", "3", "2"], "answer": 2, "explain": "`\"banana\"` dagi turli harflar: b, a, n — 3 ta.", "code": "print(len(set(\"banana\")))"}, {"t": "task", "title": "So'zlarni sanash", "text": "Gapni so'rang va har bir so'z necha marta uchrashini lug'at yordamida chiqaring.", "starter": "sozlar = input().split()\nsanoq = {}\nfor s in sozlar:\n    sanoq[s] = ...\nprint(sanoq)", "hint": "`sanoq.get(s, 0) + 1`"}, {"t": "summary", "title": "Lug'at va to'plam", "items": ["Lug'at: kalit → qiymat, nom bo'yicha tez topadi", "`d.get(k, standart)` — xatosiz o'qish", "To'plam takrorlarni olib tashlaydi", "`&` kesishma, `|` birlashma, `-` ayirma"]}]$s$::jsonb
