  UPDATE topics SET slides = $s$[{"t": "title", "title": "while sikli", "subtitle": "Shart bajarilguncha takrorlash", "emoji": "🔁"}, {"t": "idea", "title": "Choy damlash", "text": "Choy damlaganda \"rangi to'q bo'lguncha kut\" deysiz. Necha daqiqa ekanini oldindan bilmaysiz — shartga qarab to'xtaysiz.\n\n`for` — necha marta takrorlash ma'lum bo'lganda, `while` — **qachon to'xtash** ma'lum bo'lganda.", "emoji": "🫖"}, {"t": "code", "title": "Sanoq", "code": "i = 1\nwhile i <= 5:\n    print(i)\n    i += 1\nprint(\"Tugadi\")", "output": "1\n2\n3\n4\n5\nTugadi", "note": "Har aylanishda avval shart tekshiriladi. `i` 6 bo'lganda shart yolg'on bo'ladi va sikl tugaydi."}, {"t": "code", "title": "Omonat hisobi", "code": "summa = 1_000_000\nyil = 0\nwhile summa < 2_000_000:\n    summa = summa * 1.2\n    yil += 1\nprint(yil, \"yilda ikki baravar bo'ladi\")", "output": "4 yilda ikki baravar bo'ladi", "note": "Yillik 20% foiz bilan pul necha yilda ikki baravar oshishini oldindan bilmaymiz — `while` aynan shunday masalalar uchun."}, {"t": "compare", "title": "Cheksiz sikl", "left": {"label": "Hech qachon tugamaydi", "code": "i = 1\nwhile i <= 5:\n    print(i)\n    # i oshirilmagan!"}, "right": {"label": "To'g'ri", "code": "i = 1\nwhile i <= 5:\n    print(i)\n    i += 1"}}, {"t": "code", "title": "break — darhol chiqish", "code": "sonlar = [4, 8, 15, 16, 23, 42]\ni = 0\nwhile i < len(sonlar):\n    if sonlar[i] > 10:\n        print(\"Birinchi 10 dan kattasi:\", sonlar[i])\n        break\n    i += 1", "output": "Birinchi 10 dan kattasi: 15"}, {"t": "table", "title": "for yoki while?", "head": ["Vaziyat", "Tanlov"], "rows": [["Ro'yxatning har bir elementi", "`for`"], ["1 dan 100 gacha", "`for` + `range`"], ["To'g'ri parol kiritilguncha", "`while`"], ["Pul yetguncha, son 1 bo'lguncha", "`while`"]]}, {"t": "quiz", "question": "Kod nima chiqaradi?", "options": ["4", "8", "2", "3"], "answer": 3, "explain": "n: 8 → 4 → 2 → 1. Sikl 3 marta aylandi.", "code": "n = 8\nqadam = 0\nwhile n > 1:\n    n //= 2\n    qadam += 1\nprint(qadam)"}, {"t": "task", "title": "Raqamlar soni", "text": "Musbat butun son so'rang va unda nechta raqam borligini `while` yordamida toping (`len(str(...))` ishlatmang).", "starter": "n = int(input())\nsoni = 0\nwhile n > 0:\n    ...\nprint(soni)", "hint": "Har qadamda `n //= 10` — oxirgi raqam tashlanadi, `soni += 1`."}, {"t": "summary", "title": "while — qisqacha", "items": ["Shart rost ekan, blok takrorlanadi", "Shartni o'zgartiruvchi qator bo'lmasa — cheksiz sikl", "`break` — darhol chiqish, `continue` — keyingi aylanish", "Necha marta ekanini bilmasangiz — `while`"]}]$s$::jsonb
   WHERE course_id = v_course AND slug = 'while-sikli';
