  IF v_n = 0 THEN RAISE WARNING 'Mavzu topilmadi: while-sikli'; END IF;
  v_jami := v_jami + v_n;

  UPDATE topics SET slides = $s$[{"t": "title", "title": "Funksiyalar", "subtitle": "Kodni bir marta yozib, ko'p marta ishlatamiz", "emoji": "🧩"}, {"t": "idea", "title": "Funksiya — choy damlagich", "text": "Har safar choy damlash qadamlarini qayta o'ylamaysiz — \"choy damla\" deysiz, xolos. Ichida nima qilinishi allaqachon ma'lum.\n\nFunksiya ham shunday: bir marta `def` bilan yoziladi, keyin nomi bilan chaqiriladi.", "emoji": "🫖"}, {"t": "code", "title": "Funksiya yaratish va chaqirish", "code": "def salomlash(ism):\n    print(f\"Salom, {ism}!\")\n\nsalomlash(\"Ali\")\nsalomlash(\"Dilnoza\")", "output": "Salom, Ali!\nSalom, Dilnoza!"}, {"t": "code", "title": "return — natija qaytarish", "code": "def chegirma(narx, foiz):\n    return narx - narx * foiz / 100\n\nyangi = chegirma(200000, 15)\nprint(yangi)\nprint(chegirma(50000, 10) + 1000)", "output": "170000.0\n46000.0", "note": "`return` qiymatni qaytaradi — uni saqlash yoki boshqa hisobda ishlatish mumkin."}, {"t": "compare", "title": "print va return farqi", "left": {"label": "Faqat chiqaradi — natijadan foydalanib bo'lmaydi", "code": "def kvadrat(x):\n    print(x * x)\n\nn = kvadrat(4) + 1   # TypeError: None + 1"}, "right": {"label": "Qaytaradi", "code": "def kvadrat(x):\n    return x * x\n\nn = kvadrat(4) + 1\nprint(n)   # 17"}}, {"t": "code", "title": "Sukut bo'yicha qiymat", "code": "def narx(soni, bitta=4000):\n    return soni * bitta\n\nprint(narx(3))\nprint(narx(3, 5000))", "output": "12000\n15000"}, {"t": "points", "title": "Yaxshi funksiya belgilari", "items": [{"e": "🎯", "text": "Bitta aniq ish bajaradi"}, {"e": "🏷️", "text": "Nomi vazifasini aytadi: `ortacha_hisobla`, `juftmi`"}, {"e": "📥", "text": "Ma'lumotni parametrdan oladi, natijani `return` bilan beradi"}, {"e": "📏", "text": "Qisqa — odatda 20 qatordan oshmaydi"}]}, {"t": "quiz", "question": "Kod nima chiqaradi?", "options": ["None", "Xato", "10", "5"], "answer": 0, "explain": "Funksiyada `return` yo'q — u `None` qaytaradi. Faqat `print` qilish natija qaytarmaydi.", "code": "def f(x):\n    y = x * 2\n\nprint(f(5))"}, {"t": "task", "title": "BMI kalkulyatori", "text": "`bmi(vazn, boy)` funksiyasini yozing: vazn (kg) / bo'y (m) kvadrati. Natijani 1 xona aniqlikda qaytarsin.", "starter": "def bmi(vazn, boy):\n    ...\n\nprint(bmi(70, 1.75))", "hint": "`return round(vazn / boy ** 2, 1)` — kutilgan natija 22.9"}, {"t": "summary", "title": "Funksiyalar", "items": ["`def nom(parametrlar):` — yaratish, `nom()` — chaqirish", "`return` natijani qaytaradi va funksiyani tugatadi", "`return` bo'lmasa — `None` qaytadi", "Takrorlanayotgan kodni funksiyaga chiqaring"]}]$s$::jsonb
