  v_jami := v_jami + v_n;

  UPDATE topics SET slides = $s$[{"t": "title", "title": "Modullar", "subtitle": "Tayyor asboblar qutisidan foydalanamiz", "emoji": "🧰"}, {"t": "idea", "title": "Velosipedni qayta ixtiro qilmang", "text": "Ildiz chiqarish, tasodifiy son, bugungi sana — bularni o'zingiz yozishingiz shart emas. Python bilan birga yuzlab tayyor **modullar** keladi. Faqat `import` deyish kifoya.", "emoji": "🚲"}, {"t": "code", "title": "math — matematika", "code": "import math\nprint(math.sqrt(144))\nprint(math.pi)\nprint(math.ceil(4.1), math.floor(4.9))", "output": "12.0\n3.141592653589793\n5 4"}, {"t": "code", "title": "random — tasodif", "code": "import random\nrandom.seed(7)\nprint(random.randint(1, 6))\nprint(random.choice([\"tosh\", \"qaychi\", \"qog'oz\"]))", "output": "3\ntosh", "note": "`seed` natijani takrorlanadigan qiladi — darsda hamma bir xil natija ko'rishi uchun. Odatda u yozilmaydi."}, {"t": "table", "title": "Kerakli modullar", "head": ["Modul", "Nima uchun"], "rows": [["`math`", "Ildiz, daraja, π, yaxlitlash"], ["`random`", "Tasodifiy son, aralashtirish"], ["`datetime`", "Sana va vaqt"], ["`statistics`", "O'rtacha, mediana"], ["`os`", "Fayl va papkalar"]]}, {"t": "code", "title": "Faqat kerakli qismni olish", "code": "from statistics import mean, median\nballar = [72, 85, 90, 64, 85]\nprint(mean(ballar), median(ballar))", "output": "79.2 85"}, {"t": "compare", "title": "Modulni ulashni unutish", "left": {"label": "Xato", "code": "print(math.sqrt(16))   # NameError"}, "right": {"label": "To'g'ri", "code": "import math\nprint(math.sqrt(16))"}}, {"t": "quiz", "question": "Kod nima chiqaradi?", "options": ["4.0", "5.0", "5", "4"], "answer": 2, "explain": "`ceil` — yuqoriga yaxlitlaydi va butun son qaytaradi.", "code": "import math\nprint(math.ceil(4.01))"}, {"t": "task", "title": "Zar tashlash", "text": "`random` yordamida ikkita zar tashlang va yig'indisini chiqaring. 10 marta takrorlab, necha marta 7 chiqqanini sanang.", "starter": "import random\nyettilar = 0\nfor _ in range(10):\n    a = random.randint(1, 6)\n    ...\nprint(yettilar)"}, {"t": "summary", "title": "Modullar", "items": ["`import modul` — butun modul, `modul.funksiya()` bilan chaqiriladi", "`from modul import nom` — faqat kerakli qism", "math, random, datetime, statistics — eng ko'p ishlatiladiganlar", "Kerakli narsani avval standart kutubxonadan qidiring"]}]$s$::jsonb
   WHERE course_id = v_course AND slug = 'modullar';
  GET DIAGNOSTICS v_n = ROW_COUNT;
