  v_jami := v_jami + v_n;

  UPDATE topics SET slides = $s$[{"t": "title", "title": "Kortej va ichma-ich tuzilmalar", "subtitle": "O'zgarmas ma'lumot va jadvallar", "emoji": "🧱"}, {"t": "idea", "title": "Pasport ma'lumotlari", "text": "Tug'ilgan sana bir marta yoziladi va o'zgarmaydi. Uni tasodifan o'zgartirib qo'yish mumkin bo'lmasligi kerak.\n\nPython'da bunday ma'lumot uchun **kortej** bor: `(2005, 3, 21)`.", "emoji": "🪪"}, {"t": "code", "title": "Kortej", "code": "sana = (2005, 3, 21)\nyil, oy, kun = sana\nprint(kun, oy, yil)\nprint(len(sana), sana[0])", "output": "21 3 2005\n3 2005"}, {"t": "code", "title": "Kortejni o'zgartirib bo'lmaydi", "code": "sana = (2005, 3, 21)\nsana[0] = 2006", "output": "TypeError: 'tuple' object does not support item assignment", "note": "Bu xato emas, himoya: muhim ma'lumot dasturning boshqa joyida buzilmaydi."}, {"t": "idea", "title": "Jadval — sinf jurnali", "text": "Jurnalda har bir qator — bitta talaba, har bir ustun — bitta fan. Python'da bu **ro'yxatlar ro'yxati**: tashqi ro'yxat — qatorlar, ichkilari — ustunlar.", "emoji": "📒"}, {"t": "code", "title": "Ikki o'lchovli ro'yxat", "code": "jurnal = [\n    [5, 4, 5],\n    [3, 4, 4],\n    [5, 5, 5],\n]\nprint(jurnal[1][2])\nfor qator in jurnal:\n    print(sum(qator) / len(qator))", "output": "4\n4.666666666666667\n3.6666666666666665\n5.0"}, {"t": "compare", "title": "Jadval yaratishdagi tuzoq", "left": {"label": "Hamma qator bitta ro'yxat", "code": "m = [[0] * 3] * 2\nm[0][0] = 9\nprint(m)   # [[9, 0, 0], [9, 0, 0]]"}, "right": {"label": "Har qator alohida", "code": "m = [[0] * 3 for _ in range(2)]\nm[0][0] = 9\nprint(m)   # [[9, 0, 0], [0, 0, 0]]"}}, {"t": "quiz", "question": "Kod nima chiqaradi?", "options": ["5", "6", "2", "3"], "answer": 0, "explain": "`a[2]` — uchinchi qator [5, 6], undagi 0-element — 5.", "code": "a = [[1, 2], [3, 4], [5, 6]]\nprint(a[2][0])"}, {"t": "task", "title": "Eng yaxshi talaba", "text": "Jurnal berilgan: har qatorda talabaning 3 ta bahosi. O'rtachasi eng yuqori bo'lgan qator raqamini (0 dan) chiqaring.", "starter": "jurnal = [[4, 5, 3], [5, 5, 4], [3, 4, 4]]\n# eng yuqori o'rtacha qaysi qatorda?", "hint": "Har qator uchun `sum(q) / len(q)` ni hisoblab, eng kattasining indeksini saqlang."}, {"t": "summary", "title": "Kortej va jadval", "items": ["Kortej `( )` — o'zgarmas ro'yxat", "`a, b = b, a` va `x, y = nuqta` — ochish", "Jadval: `jadval[qator][ustun]`", "Jadvalni `[[0]*m for _ in range(n)]` bilan yarating"]}]$s$::jsonb
   WHERE course_id = v_course AND slug = 'kortej-va-ichma-ich-tuzilmalar';
