  v_jami := v_jami + v_n;

  UPDATE topics SET slides = $s$[{"t": "title", "title": "Istisnolar: try / except", "subtitle": "Dastur yiqilmasligi kerak", "emoji": "🛟"}, {"t": "idea", "title": "Bankomat o'chib qolmaydi", "text": "Bankomatga noto'g'ri PIN kiritsangiz, u o'chib qolmaydi — \"PIN noto'g'ri\" deydi va yana so'raydi.\n\nYaxshi dastur ham kutilmagan kiritmaga **xushmuomala javob** beradi. Buning vositasi — `try` / `except`.", "emoji": "🏧"}, {"t": "code", "title": "Xatoni ushlash", "code": "kiritma = \"o'n\"\ntry:\n    son = int(kiritma)\n    print(son * 2)\nexcept ValueError:\n    print(\"Iltimos, raqam bilan yozing\")", "output": "Iltimos, raqam bilan yozing"}, {"t": "code", "title": "Har xil xatoga har xil javob", "code": "def bol(a, b):\n    try:\n        return a / b\n    except ZeroDivisionError:\n        return \"Nolga bo'lib bo'lmaydi\"\n    except TypeError:\n        return \"Faqat sonlar\"\n\nprint(bol(10, 4))\nprint(bol(10, 0))\nprint(bol(10, \"x\"))", "output": "2.5\nNolga bo'lib bo'lmaydi\nFaqat sonlar"}, {"t": "table", "title": "try bloklari", "head": ["Blok", "Qachon bajariladi"], "rows": [["`try`", "Doim — xavfli kod shu yerda"], ["`except Tur`", "Shu turdagi xato chiqsa"], ["`else`", "Xato chiqmasa"], ["`finally`", "Har doim — tozalash ishlari"]]}, {"t": "code", "title": "To'g'ri qiymat kiritilguncha", "code": "kiritmalar = [\"abc\", \"-\", \"25\"]\nfor k in kiritmalar:\n    try:\n        yosh = int(k)\n        break\n    except ValueError:\n        print(k, \"— son emas, qaytadan\")\nprint(\"Yosh:\", yosh)", "output": "abc — son emas, qaytadan\n- — son emas, qaytadan\nYosh: 25"}, {"t": "compare", "title": "Hamma xatoni yutib yuborish", "left": {"label": "Yomon odat", "code": "try:\n    natija = hisobla()\nexcept:\n    pass   # nima bo'lganini hech kim bilmaydi"}, "right": {"label": "Aniq tur", "code": "try:\n    natija = int(input())\nexcept ValueError:\n    natija = 0"}}, {"t": "quiz", "question": "Kod nima chiqaradi?", "options": ["xato", "xato\ntamom", "ZeroDivisionError", "tamom"], "answer": 1, "explain": "Nolga bo'lishda `except` ishlaydi, `finally` esa har doim bajariladi.", "code": "try:\n    print(1 / 0)\nexcept ZeroDivisionError:\n    print(\"xato\")\nfinally:\n    print(\"tamom\")"}, {"t": "task", "title": "Xavfsiz kalkulyator", "text": "Ikki sonni so'rang va bo'linmasini chiqaring. Son kiritilmasa \"Son kiriting\", ikkinchisi 0 bo'lsa \"Nolga bo'lib bo'lmaydi\" deb chiqaring.", "starter": "try:\n    a = int(input())\n    b = int(input())\n    print(a / b)\nexcept ...:\n    ...", "hint": "Ikkita `except`: `ValueError` va `ZeroDivisionError`."}, {"t": "summary", "title": "Istisnolar", "items": ["`try` — xavfli kod, `except Tur` — javob", "`else` — xato bo'lmasa, `finally` — har doim", "Har doim aniq xato turini yozing", "Foydalanuvchi kiritmasi — `try` eng kerak joy"]}]$s$::jsonb
   WHERE course_id = v_course AND slug = 'istisnolar-try-except';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN RAISE WARNING 'Mavzu topilmadi: istisnolar-try-except'; END IF;
  v_jami := v_jami + v_n;

  UPDATE topics SET slides = $s$[{"t": "title", "title": "Fayllar bilan ishlash", "subtitle": "Ma'lumot dastur yopilgandan keyin ham saqlansin", "emoji": "🗃️"}, {"t": "idea", "title": "Daftar va doska", "text": "Doskadagi yozuv dars tugashi bilan o'chiriladi — bu o'zgaruvchilar. Daftarga yozilgani esa ertaga ham turadi — bu **fayl**.\n\nRekordlar, sozlamalar, ro'yxatlar faylda saqlanadi.", "emoji": "📓"}, {"t": "table", "title": "Ochish rejimlari", "head": ["Rejim", "Ma'nosi", "Fayl bo'lmasa"], "rows": [["`\"r\"`", "O'qish", "Xato"], ["`\"w\"`", "Yozish — eski mazmun o'chadi", "Yaratiladi"], ["`\"a\"`", "Oxiriga qo'shish", "Yaratiladi"]]}, {"t": "code", "title": "Yozish va o'qish", "code": "with open(\"rekord.txt\", \"w\", encoding=\"utf-8\") as f:\n    f.write(\"Ali 120\\n\")\n    f.write(\"Vali 95\\n\")\n\nwith open(\"rekord.txt\", encoding=\"utf-8\") as f:\n    for qator in f:\n        ism, ball = qator.split()\n        print(ism, \"->\", ball)", "output": "Ali -> 120\nVali -> 95", "note": "`with` blokidan chiqqanda fayl o'zi yopiladi. `encoding=\"utf-8\"` o'zbekcha harflar uchun."}, {"t": "code", "title": "Oxiriga qo'shish", "code": "with open(\"rekord.txt\", \"a\", encoding=\"utf-8\") as f:\n    f.write(\"Sardor 150\\n\")\n\nwith open(\"rekord.txt\", encoding=\"utf-8\") as f:\n    print(len(f.readlines()), \"ta yozuv\")", "output": "3 ta yozuv"}, {"t": "compare", "title": "\"w\" rejimi xavfi", "left": {"label": "Ehtiyotsiz", "code": "with open(\"ballar.txt\", \"w\") as f:\n    f.write(\"yangi\")   # eski 100 ta yozuv o'chdi!"}, "right": {"label": "Qo'shish kerak bo'lsa", "code": "with open(\"ballar.txt\", \"a\") as f:\n    f.write(\"yangi\\n\")"}}, {"t": "code", "title": "Fayl topilmasa", "code": "try:\n    with open(\"yoq_fayl.txt\", encoding=\"utf-8\") as f:\n        print(f.read())\nexcept FileNotFoundError:\n    print(\"Fayl yo'q — standart sozlama ishlatiladi\")", "output": "Fayl yo'q — standart sozlama ishlatiladi"}, {"t": "quiz", "question": "Qaysi rejim faylning eski mazmunini o'chiradi?", "options": ["\"w\"", "\"a\"", "\"r\"", "Hech biri"], "answer": 0, "explain": "\"w\" ochilgan zahoti faylni bo'shatadi. Qo'shish uchun \"a\" ishlatiladi."}, {"t": "task", "title": "Kundalik", "text": "Kompyuteringizda sinab ko'ring: har ishga tushganda `kundalik.txt` ga bitta qator qo'shadigan va keyin butun faylni chiqaradigan dastur yozing.", "starter": "matn = input(\"Bugun nima qildingiz? \")\nwith open(\"kundalik.txt\", \"a\", encoding=\"utf-8\") as f:\n    ...", "hint": "Platforma serverida faylga yozish cheklangan — bu topshiriqni kompyuterda yoki Pydroid'da bajaring."}, {"t": "summary", "title": "Fayllar", "items": ["`with open(nom, rejim, encoding=\"utf-8\") as f:` — doim shu shakl", "`\"r\"` o'qish, `\"w\"` qayta yozish, `\"a\"` qo'shish", "`for qator in f:` — qatorma-qator o'qish", "`FileNotFoundError` ni `try` bilan ushlang"]}]$s$::jsonb
   WHERE course_id = v_course AND slug = 'fayllar-bilan-ishlash';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN RAISE WARNING 'Mavzu topilmadi: fayllar-bilan-ishlash'; END IF;
  v_jami := v_jami + v_n;

  UPDATE topics SET slides = $s$[{"t": "title", "title": "Rekursiya", "subtitle": "O'zini chaqiradigan funksiya", "emoji": "🪆"}, {"t": "idea", "title": "Matryoshka", "text": "Matryoshkani ochasiz — ichida yana matryoshka. Yana ochasiz... Eng kichigi ochilmaydi va shu yerda to'xtaysiz.\n\nRekursiya ham shunday: funksiya o'zini **kichikroq masala** bilan chaqiradi, eng oddiy holatda esa to'xtaydi.", "emoji": "🪆"}, {"t": "points", "title": "Ikki majburiy qism", "items": [{"e": "🛑", "text": "**Asosiy holat** — javob tayyor, chaqiruv to'xtaydi"}, {"e": "🔽", "text": "**Rekursiv qadam** — masala kichrayib, funksiya o'zini chaqiradi"}]}, {"t": "code", "title": "Faktorial", "code": "def faktorial(n):\n    if n <= 1:\n        return 1\n    return n * faktorial(n - 1)\n\nprint(faktorial(5))\nprint(faktorial(10))", "output": "120\n3628800", "note": "5! = 5 × 4! = 5 × 4 × 3! ... 1! = 1 bo'lganda to'xtaydi."}, {"t": "code", "title": "Chaqiruvlarni ko'rish", "code": "def ochish(n, chuqurlik=0):\n    print(\"  \" * chuqurlik + f\"matryoshka {n}\")\n    if n > 1:\n        ochish(n - 1, chuqurlik + 1)\n\nochish(4)", "output": "matryoshka 4\n  matryoshka 3\n    matryoshka 2\n      matryoshka 1"}, {"t": "compare", "title": "Asosiy holat unutilsa", "left": {"label": "Cheksiz chaqiruv — RecursionError", "code": "def f(n):\n    return f(n - 1)"}, "right": {"label": "To'xtaydi", "code": "def f(n):\n    if n == 0:\n        return 0\n    return f(n - 1)"}}, {"t": "code", "title": "Raqamlar yig'indisi", "code": "def raqamlar(n):\n    if n < 10:\n        return n\n    return n % 10 + raqamlar(n // 10)\n\nprint(raqamlar(2026))", "output": "10"}, {"t": "quiz", "question": "Kod nima chiqaradi?", "options": ["abc", "a", "cba", "bca"], "answer": 2, "explain": "Har qadamda birinchi harf oxirga o'tadi — satr teskari bo'ladi.", "code": "def f(s):\n    if len(s) <= 1:\n        return s\n    return f(s[1:]) + s[0]\n\nprint(f(\"abc\"))"}, {"t": "task", "title": "Daraja (rekursiv)", "text": "`daraja(a, n)` funksiyasini rekursiya bilan yozing: aⁿ = a × aⁿ⁻¹, a⁰ = 1. `**` ishlatmang.", "starter": "def daraja(a, n):\n    ...\n\nprint(daraja(2, 10))", "hint": "Asosiy holat: `n == 0` bo'lsa 1 qaytaring."}, {"t": "summary", "title": "Rekursiya", "items": ["Asosiy holat + kichraytirilgan o'z-o'zini chaqirish", "Asosiy holat yo'q bo'lsa — `RecursionError`", "Daraxtsimon masalalar uchun qulay", "Oddiy hisoblarda sikl tezroq"]}]$s$::jsonb
   WHERE course_id = v_course AND slug = 'rekursiya';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN RAISE WARNING 'Mavzu topilmadi: rekursiya'; END IF;
  v_jami := v_jami + v_n;

  UPDATE topics SET slides = $s$[{"t": "title", "title": "Saralash va qidiruv", "subtitle": "Tez topish va tartibga solish san'ati", "emoji": "🔎"}, {"t": "idea", "title": "Lug'atdan so'z qidirish", "text": "Qalin lug'atdan \"kitob\" so'zini qidirasiz. Birinchi betdan varaqlamaysiz — o'rtasini ochasiz, \"k\" oldinroqmi yoki keyinmi, qaraysiz va yarmini tashlaysiz.\n\nBu **ikkilik qidiruv** — har qadamda qidiruv sohasi ikki baravar qisqaradi.", "emoji": "📖"}, {"t": "code", "title": "Chiziqli qidiruv — birma-bir", "code": "royxat = [7, 3, 9, 1, 5]\nnishon = 9\nfor i, x in enumerate(royxat):\n    if x == nishon:\n        print(\"Topildi, indeks:\", i)\n        break", "output": "Topildi, indeks: 2"}, {"t": "code", "title": "Ikkilik qidiruv", "code": "sonlar = list(range(0, 1000, 2))\nnishon = 778\nchap, ong, qadam = 0, len(sonlar) - 1, 0\nwhile chap <= ong:\n    qadam += 1\n    orta = (chap + ong) // 2\n    if sonlar[orta] == nishon:\n        break\n    if sonlar[orta] < nishon:\n        chap = orta + 1\n    else:\n        ong = orta - 1\nprint(\"Indeks:\", orta, \" qadamlar:\", qadam)", "output": "Indeks: 389  qadamlar: 5", "note": "500 ta elementdan 10 qadamdan kamroqda topildi. Shart: ro'yxat tartiblangan bo'lishi kerak."}, {"t": "table", "title": "Qadamlar soni", "head": ["Elementlar", "Chiziqli", "Ikkilik"], "rows": [["1 000", "1 000 gacha", "10 gacha"], ["1 000 000", "1 000 000 gacha", "20 gacha"]]}, {"t": "code", "title": "Amalda — sorted()", "code": "talabalar = [(\"Ali\", 87), (\"Vali\", 92), (\"Dilnoza\", 87)]\nfor ism, ball in sorted(talabalar, key=lambda t: (-t[1], t[0])):\n    print(ism, ball)", "output": "Vali 92\nAli 87\nDilnoza 87", "note": "Kalit — ball kamayishi, teng bo'lsa ism. `key` nima bo'yicha saralashni aytadi."}, {"t": "compare", "title": "sort() va sorted()", "left": {"label": "Kutilmagan None", "code": "a = [3, 1, 2]\nb = a.sort()\nprint(b)   # None"}, "right": {"label": "To'g'ri", "code": "a = [3, 1, 2]\nb = sorted(a)\nprint(b)   # [1, 2, 3]"}}, {"t": "quiz", "question": "Ikkilik qidiruv uchun qaysi shart majburiy?", "options": ["Takrorlar bo'lmasligi", "Juft uzunlik", "Ro'yxat tartiblangan bo'lishi", "Faqat butun sonlar"], "answer": 2, "explain": "O'rtadagi element bilan solishtirib qaysi yarmini tashlash faqat tartiblangan ro'yxatda to'g'ri ishlaydi."}, {"t": "task", "title": "Reyting jadvali", "text": "Talabalar ro'yxatini ball kamayishi bo'yicha, teng bo'lsa ism bo'yicha saralab, \"1. Ism ball\" ko'rinishida chiqaring.", "starter": "talabalar = [(\"Sardor\", 75), (\"Ali\", 87), (\"Vali\", 92), (\"Dilnoza\", 87)]\n# saralang va chiqaring", "hint": "`enumerate(sorted(...), 1)` — raqamlashni 1 dan boshlaydi."}, {"t": "summary", "title": "Saralash va qidiruv", "items": ["Tartiblanmagan ro'yxat — chiziqli qidiruv", "Tartiblangan ro'yxat — ikkilik qidiruv, juda tez", "Amalda `sorted(..., key=..., reverse=...)`", "`sort()` joyida saralaydi va `None` qaytaradi"]}]$s$::jsonb
   WHERE course_id = v_course AND slug = 'saralash-va-qidiruv';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN RAISE WARNING 'Mavzu topilmadi: saralash-va-qidiruv'; END IF;
  v_jami := v_jami + v_n;

  UPDATE topics SET slides = $s$[{"t": "title", "title": "Obyektga yo'naltirilgan dasturlash", "subtitle": "Ma'lumot va amallarni bitta qutiga joylaymiz", "emoji": "🏗️"}, {"t": "idea", "title": "Sinf — chizma, obyekt — uy", "text": "Bitta uy loyihasidan (chizmadan) yuzta uy qurish mumkin. Hammasining tuzilishi bir xil, lekin rangi va egasi har xil.\n\n**Sinf** — chizma, **obyekt** — undan qurilgan aniq uy.", "emoji": "🏠"}, {"t": "code", "title": "Birinchi sinf", "code": "class Talaba:\n    def __init__(self, ism, kurs):\n        self.ism = ism\n        self.kurs = kurs\n        self.ballar = []\n\n    def ball_qosh(self, b):\n        self.ballar.append(b)\n\n    def ortacha(self):\n        return sum(self.ballar) / len(self.ballar)\n\nali = Talaba(\"Ali\", 1)\nali.ball_qosh(85)\nali.ball_qosh(91)\nprint(ali.ism, ali.ortacha())", "output": "Ali 88.0"}, {"t": "table", "title": "Atamalar", "head": ["Atama", "Ma'nosi"], "rows": [["`class`", "Sinf — andoza"], ["`__init__`", "Obyekt yaratilganda ishlaydi"], ["`self`", "Shu obyektning o'zi"], ["Atribut", "`self.ism` — obyekt ma'lumoti"], ["Metod", "Sinf ichidagi funksiya"]]}, {"t": "code", "title": "Har bir obyekt mustaqil", "code": "class Hisob:\n    def __init__(self, egasi):\n        self.egasi = egasi\n        self.balans = 0\n\n    def toldir(self, s):\n        self.balans += s\n\na = Hisob(\"Ali\")\nb = Hisob(\"Vali\")\na.toldir(50000)\nprint(a.balans, b.balans)", "output": "50000 0"}, {"t": "code", "title": "Meros", "code": "class Hayvon:\n    def __init__(self, nom):\n        self.nom = nom\n    def tanishtir(self):\n        return f\"{self.nom}: {self.ovoz()}\"\n    def ovoz(self):\n        return \"...\"\n\nclass Mushuk(Hayvon):\n    def ovoz(self):\n        return \"miyov\"\n\nclass It(Hayvon):\n    def ovoz(self):\n        return \"vov\"\n\nfor h in [Mushuk(\"Mosh\"), It(\"Bobik\")]:\n    print(h.tanishtir())", "output": "Mosh: miyov\nBobik: vov", "note": "`tanishtir` bir marta yozilgan, lekin har bir hayvon o'z ovozini ishlatadi."}, {"t": "compare", "title": "self ni unutish", "left": {"label": "Xato", "code": "class A:\n    def salom():\n        print(\"salom\")\n\nA().salom()   # TypeError"}, "right": {"label": "To'g'ri", "code": "class A:\n    def salom(self):\n        print(\"salom\")\n\nA().salom()"}}, {"t": "quiz", "question": "Kod nima chiqaradi?", "options": ["2 1", "3 3", "2 2", "1 1"], "answer": 0, "explain": "Har bir obyektning o'z `n` atributi bor: a ikki marta, b bir marta oshirildi.", "code": "class S:\n    def __init__(self):\n        self.n = 0\n    def bos(self):\n        self.n += 1\n\na = S(); b = S()\na.bos(); a.bos(); b.bos()\nprint(a.n, b.n)"}, {"t": "task", "title": "To'rtburchak sinfi", "text": "`Tortburchak` sinfini yarating: eni va bo'yi, `yuza()` va `perimetr()` metodlari bilan.", "starter": "class Tortburchak:\n    def __init__(self, en, boy):\n        ...\n\nt = Tortburchak(3, 4)\nprint(t.yuza(), t.perimetr())", "hint": "Kutilgan natija: 12 14"}, {"t": "summary", "title": "OOP asoslari", "items": ["Sinf — andoza, obyekt — undan yaratilgan nusxa", "`__init__` boshlang'ich holatni o'rnatadi", "Metodlarning birinchi parametri — `self`", "Meros: `class Bola(Ota):` — kodni takrorlamasdan kengaytirish"]}]$s$::jsonb
   WHERE course_id = v_course AND slug = 'oop-asoslari';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN RAISE WARNING 'Mavzu topilmadi: oop-asoslari'; END IF;
  v_jami := v_jami + v_n;

  UPDATE topics SET slides = $s$[{"t": "title", "title": "Python va sun'iy intellekt", "subtitle": "Kurs davomida o'rganganlaringiz AI'ning poydevori", "emoji": "🤖"}, {"t": "idea", "title": "AI ham dastur", "text": "Sun'iy intellekt sehr emas. Uning ichida siz o'rgangan narsalar ishlaydi: ro'yxatlar, sikllar, funksiyalar va juda ko'p sonlar ustida arifmetika.\n\nFarqi — qoidalarni odam yozmaydi, dastur ularni **misollardan o'zi o'rganadi**.", "emoji": "🧠"}, {"t": "compare", "title": "Oddiy dastur va mashinali o'qitish", "left": {"label": "Qoidani odam yozadi", "code": "def spam_mi(xat):\n    return \"yutuq\" in xat or \"bepul\" in xat"}, "right": {"label": "Qoidani misollardan o'rganadi", "code": "# 10 000 ta belgilangan xat beriladi\n# model qaysi so'zlar spamga xosligini\n# o'zi hisoblab chiqadi"}}, {"t": "code", "title": "Eng oddiy \"o'rganish\" — o'rtacha", "code": "maydon = [40, 55, 70, 85]      # kv.m\nnarx = [400, 550, 700, 850]    # ming dollar\nkoef = sum(n / m for n, m in zip(narx, maydon)) / len(maydon)\nprint(\"1 kv.m narxi:\", koef)\nprint(\"100 kv.m bashorati:\", koef * 100)", "output": "1 kv.m narxi: 10.0\n100 kv.m bashorati: 1000.0", "note": "Model misollardan bitta son — koeffitsiyentni o'rgandi va yangi uy narxini bashorat qildi. Haqiqiy modellarda bunday sonlar milliardlab bo'ladi."}, {"t": "table", "title": "Python AI kutubxonalari", "head": ["Kutubxona", "Vazifasi"], "rows": [["NumPy", "Katta sonli massivlar bilan tez hisob"], ["Pandas", "Jadval ma'lumotlar tahlili"], ["scikit-learn", "Klassik mashinali o'qitish"], ["PyTorch, TensorFlow", "Neyron tarmoqlar"]]}, {"t": "points", "title": "AI bilan ishlashda odob", "items": [{"e": "✅", "text": "AI — yordamchi: tushuntirish so'rang, tayyor javobni ko'chirmang"}, {"e": "🔍", "text": "AI xato qiladi — natijani doim tekshiring"}, {"e": "🔐", "text": "Shaxsiy ma'lumotlarni AI'ga yubormang"}]}, {"t": "quiz", "question": "Mashinali o'qitishda qoidalarni kim yaratadi?", "options": ["Hech kim — qoidalar kerak emas", "Model ularni misollardan o'zi topadi", "Dasturchi har bir qoidani qo'lda yozadi", "Foydalanuvchi"], "answer": 1, "explain": "Asosiy farq shu: dasturchi model tuzilishini va misollarni beradi, qoidalar esa o'qitish jarayonida paydo bo'ladi."}, {"t": "task", "title": "Bashorat qiluvchi", "text": "Talabaning dars soatlari va bali berilgan. Bir soatga o'rtacha qancha ball to'g'ri kelishini hisoblab, 12 soat o'qigan talabaning balini bashorat qiling.", "starter": "soat = [2, 4, 6, 8]\nball = [20, 38, 61, 79]\n# koeffitsiyent va bashorat", "hint": "Har bir juftlik uchun `ball / soat`, keyin o'rtachasi."}, {"t": "summary", "title": "Kursning yakuni", "items": ["AI ichida o'rgangan asoslaringiz ishlaydi", "Mashinali o'qitish — qoidani misollardan topish", "NumPy, Pandas, scikit-learn — keyingi qadam", "AI'dan o'rganish uchun foydalaning, uning o'rniga emas"]}]$s$::jsonb
   WHERE course_id = v_course AND slug = 'python-va-suniy-intellekt';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN RAISE WARNING 'Mavzu topilmadi: python-va-suniy-intellekt'; END IF;
  v_jami := v_jami + v_n;

  RAISE NOTICE 'Taqdimot qo''shildi: % ta mavzu', v_jami;
END $$;
